SELECT "NAME" FROM ( SELECT * FROM ( SELECT "EXPRESSIONS_WINDOW_EMPLOYEE"."NAME" AS "NAME", CASE WHEN (RANK() OVER (PARTITION BY "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT" ORDER BY "EXPRESSIONS_WINDOW_EMPLOYEE"."SALARY" DESC) = %s) THEN CAST(%s AS BOOLEAN) ELSE CAST(%s AS BOOLEAN) END AS "QUAL0" FROM "EXPRESSIONS_WINDOW_EMPLOYEE" ORDER BY 1 ASC ) "QUALIFY" WHERE "QUAL0" = TRUE ) "QUALIFY_MASK" ORDER BY 1 ASC;
SELECT "NAME" FROM ( SELECT * FROM ( SELECT "EXPRESSIONS_WINDOW_EMPLOYEE"."NAME" AS "NAME", CASE WHEN (RANK() OVER (PARTITION BY "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT" ORDER BY "EXPRESSIONS_WINDOW_EMPLOYEE"."SALARY" DESC) = %s) THEN TRUE WHEN NOT ((RANK() OVER (PARTITION BY "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT" ORDER BY "EXPRESSIONS_WINDOW_EMPLOYEE"."SALARY" DESC) = %s)) THEN FALSE END AS "QUAL0" FROM "EXPRESSIONS_WINDOW_EMPLOYEE" ORDER BY 1 ASC ) "QUALIFY" WHERE "QUAL0" = TRUE ) "QUALIFY_MASK" ORDER BY 1 ASC;
SELECT "NAME" FROM ( SELECT * FROM ( SELECT "EXPRESSIONS_WINDOW_EMPLOYEE"."NAME" AS "NAME", RANK() OVER (PARTITION BY "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT" ORDER BY "EXPRESSIONS_WINDOW_EMPLOYEE"."SALARY" DESC) AS "QUAL0" FROM "EXPRESSIONS_WINDOW_EMPLOYEE" ORDER BY 1 ASC ) "QUALIFY" WHERE "QUAL0" = %s ) "QUALIFY_MASK" ORDER BY 1 ASC;
SELECT "NAME" FROM ( SELECT * FROM ( SELECT "EXPRESSIONS_WINDOW_EMPLOYEE"."NAME" AS "NAME", RANK() OVER (PARTITION BY "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT" ORDER BY "EXPRESSIONS_WINDOW_EMPLOYEE"."SALARY" DESC) AS "QUAL0" FROM "EXPRESSIONS_WINDOW_EMPLOYEE" WHERE "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT" IN (%s, %s) ORDER BY 1 ASC ) "QUALIFY" WHERE "QUAL0" = %s ) "QUALIFY_MASK" ORDER BY 1 ASC;
SELECT "NAME" FROM ( SELECT * FROM ( SELECT "EXPRESSIONS_WINDOW_EMPLOYEE"."NAME" AS "NAME", "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT" AS "QUAL0", RANK() OVER (PARTITION BY "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT" ORDER BY "EXPRESSIONS_WINDOW_EMPLOYEE"."SALARY" DESC) AS "QUAL1" FROM "EXPRESSIONS_WINDOW_EMPLOYEE" ORDER BY 1 ASC ) "QUALIFY" WHERE ("QUAL1" = %s OR "QUAL0" IN (CAST(%s AS NVARCHAR(32)), CAST(%s AS NVARCHAR(32)))) ) "QUALIFY_MASK" ORDER BY 1 ASC;
SELECT "NAME" FROM ( SELECT * FROM ( SELECT "EXPRESSIONS_WINDOW_EMPLOYEE"."NAME" AS "NAME", "EXPRESSIONS_WINDOW_EMPLOYEE"."SALARY" AS "QUAL0", MAX("EXPRESSIONS_WINDOW_EMPLOYEE"."SALARY") OVER (PARTITION BY "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT") AS "QUAL1" FROM "EXPRESSIONS_WINDOW_EMPLOYEE" ORDER BY 1 ASC ) "QUALIFY" WHERE "QUAL1" = ("QUAL0") ) "QUALIFY_MASK" ORDER BY 1 ASC;
SELECT "NAME", "PAST_DEPARTMENT_COUNT" FROM ( SELECT * FROM ( SELECT "EXPRESSIONS_WINDOW_EMPLOYEE"."NAME" AS "NAME", COUNT("EXPRESSIONS_WINDOW_PASTEMPLOYEEDEPARTMENT"."ID") AS "PAST_DEPARTMENT_COUNT", RANK() OVER (PARTITION BY "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT" ORDER BY "EXPRESSIONS_WINDOW_EMPLOYEE"."SALARY" DESC) AS "QUAL0" FROM "EXPRESSIONS_WINDOW_EMPLOYEE" LEFT OUTER JOIN "EXPRESSIONS_WINDOW_PASTEMPLOYEEDEPARTMENT" ON ("EXPRESSIONS_WINDOW_EMPLOYEE"."ID" = "EXPRESSIONS_WINDOW_PASTEMPLOYEEDEPARTMENT"."EMPLOYEE_ID") GROUP BY "EXPRESSIONS_WINDOW_EMPLOYEE"."NAME", "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT", "EXPRESSIONS_WINDOW_EMPLOYEE"."SALARY" HAVING COUNT("EXPRESSIONS_WINDOW_PASTEMPLOYEEDEPARTMENT"."ID") >= %s ORDER BY 1 ASC ) "QUALIFY" WHERE "QUAL0" = %s ) "QUALIFY_MASK" ORDER BY 1 ASC;
SELECT "NAME", "PAST_DEPARTMENT_COUNT" FROM ( SELECT * FROM ( SELECT "EXPRESSIONS_WINDOW_EMPLOYEE"."NAME" AS "NAME", COUNT("EXPRESSIONS_WINDOW_PASTEMPLOYEEDEPARTMENT"."ID") AS "PAST_DEPARTMENT_COUNT", RANK() OVER (PARTITION BY "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT" ORDER BY "EXPRESSIONS_WINDOW_EMPLOYEE"."SALARY" DESC) AS "QUAL0" FROM "EXPRESSIONS_WINDOW_EMPLOYEE" LEFT OUTER JOIN "EXPRESSIONS_WINDOW_PASTEMPLOYEEDEPARTMENT" ON ("EXPRESSIONS_WINDOW_EMPLOYEE"."ID" = "EXPRESSIONS_WINDOW_PASTEMPLOYEEDEPARTMENT"."EMPLOYEE_ID") GROUP BY "EXPRESSIONS_WINDOW_EMPLOYEE"."NAME", "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT", "EXPRESSIONS_WINDOW_EMPLOYEE"."SALARY" ORDER BY 1 ASC ) "QUALIFY" WHERE ("QUAL0" = %s OR "PAST_DEPARTMENT_COUNT" >= %s) ) "QUALIFY_MASK" ORDER BY 1 ASC;
SELECT "UPPER1" FROM ( SELECT * FROM ( SELECT UPPER("EXPRESSIONS_WINDOW_EMPLOYEE"."NAME") AS "UPPER1", RANK() OVER (PARTITION BY "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT" ORDER BY "EXPRESSIONS_WINDOW_EMPLOYEE"."SALARY" DESC) AS "QUAL0", "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT" AS "QUAL1", "EXPRESSIONS_WINDOW_EMPLOYEE"."NAME" AS "QUAL2" FROM "EXPRESSIONS_WINDOW_EMPLOYEE" ORDER BY "EXPRESSIONS_WINDOW_EMPLOYEE"."DEPARTMENT" ASC, "EXPRESSIONS_WINDOW_EMPLOYEE"."NAME" ASC ) "QUALIFY" WHERE "QUAL0" = %s ) "QUALIFY_MASK" ORDER BY "QUAL1" ASC, "QUAL2" ASC;
